module.exports = [
{ e: "🏹", art: { b: "🛖", s: ["🌳", "🦜", "🛶", "☀️"], c: ["#0B4F2C", "#1E8C4E"] },
pt: { h: "O vovô abriu um álbum grande, com páginas cheias de espaços vazios. “Este é o Álbum do Brasil”, disse. “Cada noite, vamos desenhar uma figurinha de um pedaço da nossa história.” Nina pegou os lápis de cor, Leo pegou a cola, e o Pipoca deitou em cima da primeira página.", t: "Os primeiros brasileiros", f: "Muito antes de chegarem os europeus, a terra que hoje chamamos de Brasil já era a casa de milhões de pessoas. Eram centenas de povos indígenas, cada um com sua língua, suas festas, suas casas e seu jeito de viver.", x: "Ainda hoje, o Brasil tem centenas de povos indígenas e mais de 270 línguas indígenas diferentes!", s: ["Os povos indígenas conheciam muito bem as plantas da floresta, os rios e os animais.", "Alguns povos moravam em aldeias com casas grandes, onde viviam várias famílias juntas.", "Os indígenas não são só do passado: eles vivem hoje no campo, nas aldeias e nas cidades."], ex: { t: "Relógio de sombra", m: "um graveto reto, um pouco de massinha ou terra, pedrinhas, um lugar com sol", p: ["Finque o graveto em pé num lugar que pega sol a manhã toda.", "De hora em hora, coloque uma pedrinha na ponta da sombra do graveto.", "Veja como a sombra anda e muda de tamanho! Povos como os Guarani observavam sombras assim para entender as estações."] }, at: "Minha aldeia em miniatura", m: "palitos de picolé, folhas secas, barbante, massinha, uma tampa de caixa", p: ["Use a tampa como chão da aldeia e espalhe um pouco de terra ou papel verde.", "Monte casinhas com os palitos e cubra com folhas secas.", "Faça um rio de papel azul e pessoas de massinha. Essa é a primeira figurinha do álbum!"], q: "O que você gostaria de perguntar para uma criança indígena sobre a vida dela?" },
en: { h: "Grandpa opened a big album with pages full of empty spaces. “This is the Brazil Album,” he said. “Every night we'll draw a sticker for one piece of our history.” Nina grabbed the colored pencils, Leo grabbed the glue, and Popcorn lay down right on top of the first page.", t: "The first Brazilians", f: "Long before Europeans arrived, the land we now call Brazil was already home to millions of people. There were hundreds of Indigenous peoples, each with its own language, celebrations, houses and way of life.", x: "Even today, Brazil has hundreds of Indigenous peoples and more than 270 different Indigenous languages!", s: ["Indigenous peoples knew the forest's plants, rivers and animals extremely well.", "Some peoples lived in villages with large houses where several families lived together.", "Indigenous people aren't just from the past: they live today in the countryside, in villages and in cities."], ex: { t: "Shadow clock", m: "a straight stick, some play dough or soil, small pebbles, a sunny spot", p: ["Stand the stick upright in a spot that gets sun all morning.", "Every hour, place a pebble at the tip of the stick's shadow.", "Watch the shadow move and change length! Peoples like the Guarani watched shadows like this to understand the seasons."] }, at: "My miniature village", m: "popsicle sticks, dry leaves, string, play dough, a box lid", p: ["Use the lid as the village ground and sprinkle a little soil or green paper on it.", "Build little houses with the sticks and cover them with dry leaves.", "Make a river from blue paper and people from play dough. That's the album's first sticker!"], q: "What would you like to ask an Indigenous kid about their life?" },
es: { h: "El abuelo abrió un álbum grande, con páginas llenas de espacios vacíos. “Este es el Álbum de Brasil”, dijo. “Cada noche vamos a dibujar una figurita de un pedazo de nuestra historia.” Nina tomó los lápices de colores, Leo tomó el pegamento, y Palomita se acostó justo encima de la primera página.", t: "Los primeros brasileños", f: "Mucho antes de que llegaran los europeos, la tierra que hoy llamamos Brasil ya era el hogar de millones de personas. Eran cientos de pueblos indígenas, cada uno con su lengua, sus fiestas, sus casas y su forma de vivir.", x: "¡Todavía hoy Brasil tiene cientos de pueblos indígenas y más de 270 lenguas indígenas diferentes!", s: ["Los pueblos indígenas conocían muy bien las plantas de la selva, los ríos y los animales.", "Algunos pueblos vivían en aldeas con casas grandes, donde vivían varias familias juntas.", "Los indígenas no son solo del pasado: viven hoy en el campo, en aldeas y en ciudades."], ex: { t: "Reloj de sombra", m: "un palito recto, un poco de plastilina o tierra, piedritas, un lugar con sol", p: ["Clava el palito de pie en un lugar donde dé el sol toda la mañana.", "Cada hora, pon una piedrita en la punta de la sombra del palito.", "¡Mira cómo la sombra se mueve y cambia de tamaño! Pueblos como los guaraníes observaban sombras así para entender las estaciones."] }, at: "Mi aldea en miniatura", m: "palitos de helado, hojas secas, cordel, plastilina, una tapa de caja", p: ["Usa la tapa como suelo de la aldea y esparce un poco de tierra o papel verde.", "Arma casitas con los palitos y cúbrelas con hojas secas.", "Haz un río de papel azul y personas de plastilina. ¡Es la primera figurita del álbum!"], q: "¿Qué te gustaría preguntarle a un niño indígena sobre su vida?" } },

{ e: "🦴", art: { b: "🏺", s: ["🦴", "🐚", "🖌️", "⛏️"], c: ["#5A3A1B", "#B07A3C"] },
pt: { h: "Leo achou uma conchinha no jardim e perguntou se era um tesouro. O vovô contou que, no litoral do Brasil, existem montanhas inteiras feitas de conchas, construídas por pessoas há milhares de anos. “Os arqueólogos cavam devagarinho para descobrir esses segredos”, explicou.", t: "Detetives do passado", f: "Os arqueólogos estudam objetos antigos para descobrir como as pessoas viviam. No Brasil, eles encontraram ossos, ferramentas, pinturas nas pedras e potes de cerâmica muito antigos.", x: "Um dos esqueletos mais antigos das Américas foi achado em Minas Gerais e ganhou o apelido de Luzia. Ela viveu há cerca de 11.500 anos!", s: ["Os sambaquis são morros feitos de conchas, ossos e restos de comida, montados por povos do litoral. Alguns têm milhares de anos.", "Na Ilha de Marajó, no Pará, um povo antigo fazia potes de cerâmica com desenhos lindos, há mais de mil anos.", "No Piauí, na Serra da Capivara, há milhares de pinturas nas rochas, feitas há muito tempo."], ex: { t: "Escavação no quintal", m: "uma bandeja funda, areia ou terra, objetos pequenos (botões, tampinhas, conchas), um pincel e uma colher", p: ["Um adulto enterra os objetos na areia, em camadas, sem você ver.", "Cave devagar com a colher e limpe com o pincel, como um arqueólogo.", "Anote em que camada achou cada coisa: o que está mais fundo foi enterrado primeiro!"] }, at: "Pote marajoara", m: "massinha ou argila, um palito", p: ["Modele um potinho com a massinha.", "Com o palito, faça desenhos de linhas, espirais e quadradinhos, como na cerâmica marajoara.", "Desenhe seu pote no álbum como a figurinha de hoje."], q: "Se um arqueólogo do futuro achasse um objeto seu, o que ele descobriria sobre você?" },
en: { h: "Leo found a little shell in the garden and asked if it was treasure. Grandpa told him that on Brazil's coast there are whole hills made of shells, built by people thousands of years ago. “Archaeologists dig very slowly to uncover these secrets,” he explained.", t: "Detectives of the past", f: "Archaeologists study old objects to find out how people lived. In Brazil, they've found very old bones, tools, rock paintings and clay pots.", x: "One of the oldest skeletons in the Americas was found in Minas Gerais and nicknamed Luzia. She lived about 11,500 years ago!", s: ["Sambaquis are mounds made of shells, bones and food scraps, built by coastal peoples. Some are thousands of years old.", "On Marajó Island, in the state of Pará, an ancient people made clay pots with beautiful designs more than a thousand years ago.", "In Piauí, in the Serra da Capivara, there are thousands of rock paintings made long, long ago."], ex: { t: "Backyard dig", m: "a deep tray, sand or soil, small objects (buttons, bottle caps, shells), a paintbrush and a spoon", p: ["A grown-up buries the objects in the sand, in layers, without you seeing.", "Dig slowly with the spoon and brush things clean, like an archaeologist.", "Write down which layer you found each thing in: what's deepest was buried first!"] }, at: "Marajoara pot", m: "play dough or clay, a toothpick", p: ["Shape a little pot from the dough.", "With the toothpick, carve lines, spirals and squares, like Marajoara pottery.", "Draw your pot in the album as today's sticker."], q: "If a future archaeologist found one of your things, what would they learn about you?" },
es: { h: "Leo encontró una conchita en el jardín y preguntó si era un tesoro. El abuelo le contó que en la costa de Brasil hay montañas enteras hechas de conchas, construidas por personas hace miles de años. “Los arqueólogos excavan despacito para descubrir esos secretos”, explicó.", t: "Detectives del pasado", f: "Los arqueólogos estudian objetos antiguos para descubrir cómo vivían las personas. En Brasil han encontrado huesos, herramientas, pinturas en las rocas y vasijas de cerámica muy antiguas.", x: "Uno de los esqueletos más antiguos de América se encontró en Minas Gerais y recibió el apodo de Luzia. ¡Vivió hace unos 11.500 años!", s: ["Los sambaquis son montículos hechos de conchas, huesos y restos de comida, armados por pueblos de la costa. Algunos tienen miles de años.", "En la isla de Marajó, en el estado de Pará, un pueblo antiguo hacía vasijas de cerámica con dibujos hermosos hace más de mil años.", "En Piauí, en la Sierra de la Capivara, hay miles de pinturas en las rocas hechas hace mucho tiempo."], ex: { t: "Excavación en casa", m: "una bandeja honda, arena o tierra, objetos pequeños (botones, tapitas, conchas), un pincel y una cuchara", p: ["Un adulto entierra los objetos en la arena, en capas, sin que lo veas.", "Excava despacio con la cuchara y limpia con el pincel, como un arqueólogo.", "Anota en qué capa encontraste cada cosa: ¡lo que está más hondo se enterró primero!"] }, at: "Vasija marajoara", m: "plastilina o arcilla, un palillo", p: ["Modela una vasijita con la plastilina.", "Con el palillo, haz dibujos de líneas, espirales y cuadraditos, como en la cerámica marajoara.", "Dibuja tu vasija en el álbum como la figurita de hoy."], q: "Si un arqueólogo del futuro encontrara un objeto tuyo, ¿qué descubriría sobre ti?" } },

{ e: "⛵", art: { b: "⛵", s: ["🌊", "🧭", "📜", "🏝️"], c: ["#0B3A5A", "#2C7AB0"] },
pt: { h: "Nina fez um barquinho de papel e soltou na bacia. “Será que ele atravessaria o oceano?”, perguntou. O vovô riu e contou sobre os navios de madeira que cruzaram o Atlântico em 1500. “Um homem a bordo escreveu uma carta contando tudo o que viu”, disse.", t: "1500: os portugueses chegam", f: "Em 22 de abril de 1500, uma frota portuguesa comandada por Pedro Álvares Cabral chegou ao litoral da Bahia. A primeira coisa que os marinheiros avistaram foi um monte, que chamaram de Monte Pascoal.", x: "Pero Vaz de Caminha, que estava na viagem, escreveu uma carta ao rei de Portugal contando como era a terra e as pessoas. Muita gente chama essa carta de “certidão de nascimento” do Brasil!", s: ["A frota de Cabral tinha 13 embarcações e ia para a Índia.", "Na carta, Caminha descreve os indígenas que encontraram na praia e a troca de presentes entre eles.", "Para os povos que já viviam aqui, a chegada dos europeus mudou tudo, e muitas vezes trouxe sofrimento."], ex: { t: "Caravela que não afunda", m: "papel-alumínio, uma bacia com água, moedas ou bolinhas de gude", p: ["Faça um barquinho com um quadrado de papel-alumínio, dobrando as bordas para cima.", "Coloque na água e vá adicionando moedas, uma de cada vez.", "Quantas ele aguenta? Tente outro formato e veja qual barco carrega mais carga!"] }, at: "Minha carta de descobridor", m: "papel, lápis", p: ["Imagine que você acabou de chegar à sua rua pela primeira vez.", "Escreva uma carta descrevendo as árvores, os animais, as casas e as pessoas.", "Dobre a carta e cole no álbum como figurinha do dia."], q: "Como você acha que os indígenas se sentiram ao ver aqueles navios enormes?" },
en: { h: "Nina made a little paper boat and set it in the basin. “Could it cross the ocean?” she asked. Grandpa laughed and told her about the wooden ships that crossed the Atlantic in 1500. “A man on board wrote a letter describing everything he saw,” he said.", t: "1500: the Portuguese arrive", f: "On April 22, 1500, a Portuguese fleet led by Pedro Álvares Cabral reached the coast of what is now Bahia. The first thing the sailors spotted was a hill, which they named Monte Pascoal.", x: "Pero Vaz de Caminha, who was on the voyage, wrote a letter to the king of Portugal describing the land and its people. Many people call that letter Brazil's “birth certificate”!", s: ["Cabral's fleet had 13 ships and was on its way to India.", "In the letter, Caminha describes the Indigenous people they met on the beach and how they exchanged gifts.", "For the peoples who already lived here, the arrival of Europeans changed everything, and often brought suffering."], ex: { t: "The unsinkable caravel", m: "aluminum foil, a basin of water, coins or marbles", p: ["Make a little boat from a square of aluminum foil, folding the edges up.", "Put it in the water and add coins one at a time.", "How many can it hold? Try a different shape and see which boat carries more cargo!"] }, at: "My explorer's letter", m: "paper, pencil", p: ["Imagine you've just arrived on your street for the very first time.", "Write a letter describing the trees, animals, houses and people.", "Fold the letter and glue it into the album as today's sticker."], q: "How do you think the Indigenous people felt when they saw those huge ships?" },
es: { h: "Nina hizo un barquito de papel y lo soltó en la palangana. “¿Podría cruzar el océano?”, preguntó. El abuelo se rió y le contó sobre los barcos de madera que cruzaron el Atlántico en 1500. “Un hombre a bordo escribió una carta contando todo lo que vio”, dijo.", t: "1500: llegan los portugueses", f: "El 22 de abril de 1500, una flota portuguesa al mando de Pedro Álvares Cabral llegó a la costa de lo que hoy es Bahía. Lo primero que vieron los marineros fue un monte, al que llamaron Monte Pascual.", x: "Pero Vaz de Caminha, que iba en el viaje, escribió una carta al rey de Portugal contando cómo eran la tierra y las personas. ¡Mucha gente llama a esa carta la “partida de nacimiento” de Brasil!", s: ["La flota de Cabral tenía 13 barcos e iba camino a la India.", "En la carta, Caminha describe a los indígenas que encontraron en la playa y el intercambio de regalos entre ellos.", "Para los pueblos que ya vivían allí, la llegada de los europeos lo cambió todo, y muchas veces trajo sufrimiento."], ex: { t: "La carabela que no se hunde", m: "papel de aluminio, una palangana con agua, monedas o canicas", p: ["Haz un barquito con un cuadrado de papel de aluminio, doblando los bordes hacia arriba.", "Ponlo en el agua y agrega monedas de a una.", "¿Cuántas aguanta? ¡Prueba otra forma y mira qué barco lleva más carga!"] }, at: "Mi carta de descubridor", m: "papel, lápiz", p: ["Imagina que acabas de llegar a tu calle por primera vez.", "Escribe una carta describiendo los árboles, los animales, las casas y las personas.", "Dobla la carta y pégala en el álbum como figurita del día."], q: "¿Cómo crees que se sintieron los indígenas al ver esos barcos enormes?" } },

{ e: "🌳", art: { b: "🌳", s: ["🔴", "🪵", "🎨", "⛵"], c: ["#5A1B1B", "#C2413A"] },
pt: { h: "Na pracinha, o vovô parou diante de uma árvore de tronco escuro e flores amarelas. “Esta árvore deu nome ao nosso país”, disse. Leo não acreditou: “Um país com nome de árvore?”. Nina já estava pegando uma florzinha do chão para colar no álbum.", t: "A árvore que deu nome ao Brasil", f: "O pau-brasil é uma árvore da Mata Atlântica. Dentro do tronco, a madeira é vermelha como brasa, e dela se fazia uma tinta usada para tingir tecidos na Europa. Por causa dessa árvore, a terra passou a se chamar Brasil.", x: "Foram cortadas tantas árvores de pau-brasil que hoje ela está ameaçada de extinção. Ela é a árvore nacional do Brasil e precisa ser protegida!", s: ["A palavra “brasil” vem de “brasa”, por causa da cor vermelha da madeira.", "Os portugueses trocavam objetos com indígenas, que cortavam e carregavam os troncos até os navios.", "A madeira do pau-brasil é usada até hoje para fazer arcos de violino muito especiais."], ex: { t: "Tinta vermelha natural", m: "uma beterraba ralada (com um adulto), um pouco de água, um pano branco velho ou papel", p: ["Misture a beterraba ralada com um pouquinho de água numa tigela.", "Coe o suco vermelho e mergulhe um pedaço de pano ou pinte o papel com ele.", "Deixe secar: você fez tinta natural, como a que se fazia com o pau-brasil!"] }, at: "Plante uma ideia", m: "papel, lápis de cor", p: ["Desenhe um pau-brasil com o tronco, as folhas e as flores amarelas.", "Escreva embaixo três jeitos de proteger as árvores.", "Cole no álbum e, se puder, plante uma semente num vasinho."], q: "Se a sua cidade tivesse nome de uma planta, qual seria?" },
en: { h: "At the little park, Grandpa stopped in front of a tree with a dark trunk and yellow flowers. “This tree gave our country its name,” he said. Leo didn't believe him: “A country named after a tree?” Nina was already picking up a little flower from the ground to glue into the album.", t: "The tree that named Brazil", f: "Brazilwood is a tree from the Atlantic Forest. Inside its trunk, the wood is red like glowing embers, and it was used to make a dye for coloring fabric in Europe. Because of this tree, the land came to be called Brazil.", x: "So many brazilwood trees were cut down that today the species is endangered. It is Brazil's national tree and needs to be protected!", s: ["The word “brasil” comes from “brasa,” Portuguese for glowing embers, because of the wood's red color.", "The Portuguese traded objects with Indigenous people, who cut the trunks and carried them to the ships.", "Brazilwood is still used today to make very special violin bows."], ex: { t: "Natural red dye", m: "a grated beet (with a grown-up), a little water, an old white cloth or paper", p: ["Mix the grated beet with a little water in a bowl.", "Strain the red juice and dip a piece of cloth in it or paint the paper with it.", "Let it dry: you made natural dye, like the dye that came from brazilwood!"] }, at: "Plant an idea", m: "paper, colored pencils", p: ["Draw a brazilwood tree with its trunk, leaves and yellow flowers.", "Underneath, write three ways to protect trees.", "Glue it into the album and, if you can, plant a seed in a little pot."], q: "If your town were named after a plant, what would it be?" },
es: { h: "En la placita, el abuelo se detuvo frente a un árbol de tronco oscuro y flores amarillas. “Este árbol le dio nombre a nuestro país”, dijo. Leo no le creyó: “¿Un país con nombre de árbol?”. Nina ya estaba levantando una florcita del suelo para pegarla en el álbum.", t: "El árbol que le dio nombre a Brasil", f: "El palo brasil es un árbol de la Mata Atlántica. Dentro del tronco, la madera es roja como una brasa, y con ella se hacía una tinta para teñir telas en Europa. Por ese árbol, la tierra pasó a llamarse Brasil.", x: "Se cortaron tantos árboles de palo brasil que hoy está en peligro de extinción. ¡Es el árbol nacional de Brasil y hay que protegerlo!", s: ["La palabra “brasil” viene de “brasa”, por el color rojo de la madera.", "Los portugueses intercambiaban objetos con los indígenas, que cortaban y cargaban los troncos hasta los barcos.", "La madera del palo brasil se usa hasta hoy para hacer arcos de violín muy especiales."], ex: { t: "Tinta roja natural", m: "una remolacha rallada (con un adulto), un poco de agua, un trapo blanco viejo o papel", p: ["Mezcla la remolacha rallada con un poquito de agua en un tazón.", "Cuela el jugo rojo y moja un pedazo de tela o pinta el papel con él.", "Déjalo secar: ¡hiciste tinta natural, como la que se hacía con el palo brasil!"] }, at: "Planta una idea", m: "papel, lápices de colores", p: ["Dibuja un palo brasil con su tronco, sus hojas y sus flores amarillas.", "Escribe debajo tres formas de proteger los árboles.", "Pégalo en el álbum y, si puedes, planta una semilla en una macetita."], q: "Si tu ciudad tuviera nombre de planta, ¿cuál sería?" } },

{ e: "🏘️", art: { b: "🏘️", s: ["⛪", "🛗", "⚓", "🗺️"], c: ["#3A2A5A", "#7A5AB0"] },
pt: { h: "Leo viu uma foto de um elevador enorme, ligando uma parte alta e uma parte baixa de uma cidade. “Que cidade é essa?”, perguntou. “Salvador, a primeira capital do Brasil”, respondeu o vovô. “Ela foi construída no alto de um morro, de frente para o mar.”", t: "As primeiras vilas e a primeira capital", f: "Os portugueses começaram a construir vilas no litoral. A primeira foi São Vicente, em 1532, onde hoje é o estado de São Paulo. Em 1549, fundaram Salvador, na Bahia, que foi a capital do Brasil por mais de 200 anos.", x: "O Elevador Lacerda, em Salvador, liga a Cidade Baixa à Cidade Alta desde 1873. Foi um dos primeiros elevadores urbanos do mundo!", s: ["Salvador foi a capital de 1549 até 1763, quando a capital passou para o Rio de Janeiro.", "As vilas tinham igreja, praça, casas e um porto para os navios.", "Muitas cidades brasileiras ainda guardam casarões e ruas de pedra dessa época."], ex: { t: "Elevador de carretel", m: "um carretel de linha vazio ou um rolo de papel, um lápis, barbante, um copinho de papel, uma fita", p: ["Passe o lápis pelo carretel e prenda o lápis entre duas pilhas de livros.", "Amarre o copinho numa ponta do barbante e passe o barbante por cima do carretel.", "Puxe a outra ponta: o copinho sobe! Coloque um bonequinho e faça a viagem até a “Cidade Alta”."] }, at: "Mapa da minha vila", m: "papel grande, lápis de cor", p: ["Desenhe o seu bairro como se fosse uma vila antiga.", "Marque onde ficariam a praça, a igreja ou o templo, o mercado e o porto (ou a rodoviária!).", "Invente um nome antigo para a sua vila e cole no álbum."], q: "Se você fosse fundar uma cidade, o que ela teria de mais legal?" },
en: { h: "Leo saw a photo of a huge elevator connecting a high part and a low part of a city. “What city is that?” he asked. “Salvador, Brazil's first capital,” Grandpa answered. “It was built on top of a hill, facing the sea.”", t: "The first towns and the first capital", f: "The Portuguese began building towns along the coast. The first was São Vicente, in 1532, in what is now the state of São Paulo. In 1549 they founded Salvador, in Bahia, which was Brazil's capital for more than 200 years.", x: "The Lacerda Elevator in Salvador has connected the Lower City to the Upper City since 1873. It was one of the first city elevators in the world!", s: ["Salvador was the capital from 1549 until 1763, when the capital moved to Rio de Janeiro.", "The towns had a church, a square, houses and a port for ships.", "Many Brazilian cities still have big old houses and stone streets from that time."], ex: { t: "Spool elevator", m: "an empty thread spool or paper roll, a pencil, string, a small paper cup, tape", p: ["Slide the pencil through the spool and rest the pencil ends between two stacks of books.", "Tie the cup to one end of the string and run the string over the spool.", "Pull the other end: the cup goes up! Put a little toy in it and ride up to the “Upper City.”"] }, at: "Map of my town", m: "large paper, colored pencils", p: ["Draw your neighborhood as if it were an old colonial town.", "Mark where the square, the church or temple, the market and the port (or the bus station!) would be.", "Make up an old-fashioned name for your town and glue it in the album."], q: "If you founded a city, what would be the coolest thing in it?" },
es: { h: "Leo vio la foto de un ascensor enorme que unía una parte alta y una parte baja de una ciudad. “¿Qué ciudad es esa?”, preguntó. “Salvador, la primera capital de Brasil”, respondió el abuelo. “Se construyó en lo alto de un cerro, frente al mar.”", t: "Las primeras villas y la primera capital", f: "Los portugueses empezaron a construir villas en la costa. La primera fue São Vicente, en 1532, donde hoy está el estado de São Paulo. En 1549 fundaron Salvador, en Bahía, que fue la capital de Brasil durante más de 200 años.", x: "¡El Ascensor Lacerda, en Salvador, une la Ciudad Baja con la Ciudad Alta desde 1873. Fue uno de los primeros ascensores urbanos del mundo!", s: ["Salvador fue la capital desde 1549 hasta 1763, cuando la capital pasó a Río de Janeiro.", "Las villas tenían iglesia, plaza, casas y un puerto para los barcos.", "Muchas ciudades brasileñas todavía conservan casonas y calles de piedra de esa época."], ex: { t: "Ascensor de carretel", m: "un carretel de hilo vacío o un rollo de papel, un lápiz, cordel, un vasito de papel, cinta", p: ["Pasa el lápiz por el carretel y apoya las puntas del lápiz entre dos pilas de libros.", "Ata el vasito a una punta del cordel y pasa el cordel por encima del carretel.", "Tira de la otra punta: ¡el vasito sube! Pon un muñequito y haz el viaje hasta la “Ciudad Alta”."] }, at: "Mapa de mi villa", m: "papel grande, lápices de colores", p: ["Dibuja tu barrio como si fuera una villa antigua.", "Marca dónde estarían la plaza, la iglesia o el templo, el mercado y el puerto (¡o la terminal de ómnibus!).", "Inventa un nombre antiguo para tu villa y pégalo en el álbum."], q: "Si fundaras una ciudad, ¿qué sería lo más genial que tendría?" } },

{ e: "🍬", art: { b: "🎋", s: ["🍬", "⚙️", "🐂", "🏭"], c: ["#4E3A0B", "#C29A2C"] },
pt: { h: "No café da manhã, Leo colocou três colheres de açúcar no leite. O vovô levantou a sobrancelha e perguntou: “Sabia que esse açúcar já foi tão valioso que era chamado de ouro branco?”. Nina quis saber de onde ele vinha, e o vovô mostrou um pedaço de cana.", t: "O tempo do açúcar", f: "Os portugueses plantaram muita cana-de-açúcar no Nordeste do Brasil. A cana era moída em engenhos, e o caldo era fervido até virar açúcar, que era vendido para a Europa por muito dinheiro.", x: "Por um bom tempo, nos anos 1600, o Brasil foi o maior produtor de açúcar do mundo!", s: ["Os engenhos tinham moendas movidas por bois, cavalos ou pela força da água.", "Os holandeses ocuparam Pernambuco por cerca de 24 anos por causa do açúcar.", "O trabalho nos engenhos era muito pesado e era feito, principalmente, por pessoas escravizadas."], ex: { t: "Corrida do açúcar", m: "dois copos transparentes, água gelada, água morna da torneira, duas colheres de açúcar", p: ["Coloque água gelada num copo e água morna no outro (peça ajuda a um adulto).", "Jogue uma colher de açúcar em cada copo ao mesmo tempo e mexa igual nos dois.", "Em qual o açúcar sumiu primeiro? Na água quentinha, ele se dissolve mais rápido!"] }, at: "Da cana até a mesa", m: "papel, lápis de cor", p: ["Divida uma folha em 4 quadrinhos.", "Desenhe: a cana no campo, a moenda, o caldo fervendo e o açúcar na mesa.", "Cole no álbum como uma figurinha em quadrinhos."], q: "Que comidas da sua casa levam açúcar? Daria para comer menos?" },
en: { h: "At breakfast, Leo put three spoonfuls of sugar in his milk. Grandpa raised an eyebrow and asked, “Did you know sugar was once so valuable it was called white gold?” Nina wanted to know where it came from, and Grandpa showed them a piece of sugarcane.", t: "The age of sugar", f: "The Portuguese planted lots of sugarcane in Brazil's Northeast. The cane was crushed in sugar mills, and the juice was boiled until it became sugar, which was sold to Europe for a lot of money.", x: "For a good while in the 1600s, Brazil was the world's biggest sugar producer!", s: ["The mills had crushers turned by oxen, horses or the power of water.", "The Dutch occupied Pernambuco for about 24 years because of sugar.", "The work in the mills was very hard and was done mainly by enslaved people."], ex: { t: "Sugar race", m: "two clear glasses, ice water, warm tap water, two spoonfuls of sugar", p: ["Pour ice water into one glass and warm tap water into the other (ask a grown-up for help).", "Drop a spoonful of sugar into each glass at the same time and stir both the same way.", "In which one did the sugar disappear first? In warm water, it dissolves faster!"] }, at: "From cane to table", m: "paper, colored pencils", p: ["Divide a sheet into 4 boxes.", "Draw: the cane in the field, the mill, the juice boiling and the sugar on the table.", "Glue it into the album as a comic-strip sticker."], q: "Which foods at home have sugar in them? Could you eat less?" },
es: { h: "En el desayuno, Leo puso tres cucharadas de azúcar en la leche. El abuelo levantó una ceja y preguntó: “¿Sabías que el azúcar llegó a ser tan valioso que lo llamaban oro blanco?”. Nina quiso saber de dónde venía, y el abuelo les mostró un pedazo de caña.", t: "La época del azúcar", f: "Los portugueses plantaron mucha caña de azúcar en el Nordeste de Brasil. La caña se molía en ingenios, y el jugo se hervía hasta convertirse en azúcar, que se vendía a Europa por mucho dinero.", x: "¡Durante buena parte del siglo XVII, Brasil fue el mayor productor de azúcar del mundo!", s: ["Los ingenios tenían molinos movidos por bueyes, caballos o la fuerza del agua.", "Los holandeses ocuparon Pernambuco durante unos 24 años por el azúcar.", "El trabajo en los ingenios era muy duro y lo hacían, sobre todo, personas esclavizadas."], ex: { t: "Carrera del azúcar", m: "dos vasos transparentes, agua helada, agua tibia de la canilla, dos cucharadas de azúcar", p: ["Pon agua helada en un vaso y agua tibia en el otro (pide ayuda a un adulto).", "Echa una cucharada de azúcar en cada vaso al mismo tiempo y revuelve igual en los dos.", "¿En cuál desapareció primero? ¡En el agua tibia se disuelve más rápido!"] }, at: "De la caña a la mesa", m: "papel, lápices de colores", p: ["Divide una hoja en 4 cuadritos.", "Dibuja: la caña en el campo, el molino, el jugo hirviendo y el azúcar en la mesa.", "Pégalo en el álbum como una figurita en historieta."], q: "¿Qué comidas de tu casa llevan azúcar? ¿Se podría comer menos?" } },

{ e: "🌍", art: { b: "🕊️", s: ["🌊", "⛵", "💔", "🌍"], c: ["#2A1B0B", "#7A4A1B"] },
pt: { h: "Naquela noite, o vovô ficou mais sério. Abriu um mapa e passou o dedo da África até o Brasil. “Hoje a figurinha é de uma parte triste da nossa história”, disse. “Mas é importante lembrar, para que nunca mais aconteça.” Nina segurou a mão dele, e o Pipoca deitou quietinho no colo do Leo.", t: "Uma história que não podemos esquecer", f: "Durante mais de 300 anos, milhões de pessoas foram trazidas à força da África para o Brasil e obrigadas a trabalhar sem receber nada e sem liberdade. Isso se chama escravidão, e foi uma enorme injustiça.", x: "O Brasil foi o país que mais recebeu africanos escravizados em todo o mundo: cerca de 4,8 milhões de pessoas chegaram aqui.", s: ["As pessoas eram arrancadas de suas famílias e atravessavam o oceano em navios apertados, em condições terríveis.", "Elas vinham de muitos povos e reinos africanos diferentes, com línguas, religiões e conhecimentos próprios.", "Mesmo sofrendo, muitas pessoas resistiram, guardaram suas tradições e lutaram pela liberdade."], ex: { t: "Quanto é um milhão?", m: "um copo pequeno, feijões ou grãos de arroz, papel e lápis", p: ["Encha o copinho de feijões e conte quantos couberam (peça ajuda para contar de dez em dez).", "Pense: quantos copinhos seriam necessários para chegar a mil? E a um milhão?", "Converse com um adulto: cada feijão seria uma pessoa com nome, família e sonhos."] }, at: "O que é liberdade?", m: "papel, lápis de cor", p: ["Pense no que significa ser livre: escolher, brincar, estar com a família, aprender.", "Desenhe o que a liberdade significa para você.", "Cole no álbum e escreva embaixo: “Liberdade é direito de todos”."], q: "Por que é importante lembrar as partes tristes da história?" },
en: { h: "That night, Grandpa grew more serious. He opened a map and traced his finger from Africa to Brazil. “Today's sticker is about a sad part of our history,” he said. “But it's important to remember it, so it never happens again.” Nina held his hand, and Popcorn lay quietly in Leo's lap.", t: "A history we must not forget", f: "For more than 300 years, millions of people were brought by force from Africa to Brazil and made to work without pay and without freedom. This is called slavery, and it was a terrible injustice.", x: "Brazil received more enslaved Africans than any other country in the world: about 4.8 million people arrived here.", s: ["People were torn from their families and crossed the ocean on crowded ships, in terrible conditions.", "They came from many different African peoples and kingdoms, with their own languages, religions and knowledge.", "Even while suffering, many people resisted, kept their traditions alive and fought for freedom."], ex: { t: "How much is a million?", m: "a small cup, beans or grains of rice, paper and pencil", p: ["Fill the cup with beans and count how many fit (get help counting by tens).", "Think: how many cups would it take to reach a thousand? A million?", "Talk with a grown-up: each bean would be a person with a name, a family and dreams."] }, at: "What is freedom?", m: "paper, colored pencils", p: ["Think about what it means to be free: to choose, to play, to be with your family, to learn.", "Draw what freedom means to you.", "Glue it into the album and write underneath: “Freedom is everyone's right.”"], q: "Why is it important to remember the sad parts of history?" },
es: { h: "Esa noche, el abuelo se puso más serio. Abrió un mapa y pasó el dedo desde África hasta Brasil. “La figurita de hoy es de una parte triste de nuestra historia”, dijo. “Pero es importante recordarla, para que nunca vuelva a pasar.” Nina le tomó la mano, y Palomita se acostó quietito en el regazo de Leo.", t: "Una historia que no podemos olvidar", f: "Durante más de 300 años, millones de personas fueron traídas a la fuerza de África a Brasil y obligadas a trabajar sin recibir nada y sin libertad. Eso se llama esclavitud, y fue una enorme injusticia.", x: "Brasil fue el país que más africanos esclavizados recibió en todo el mundo: cerca de 4,8 millones de personas llegaron aquí.", s: ["Las personas eran arrancadas de sus familias y cruzaban el océano en barcos apretados, en condiciones terribles.", "Venían de muchos pueblos y reinos africanos diferentes, con sus propias lenguas, religiones y conocimientos.", "Aun sufriendo, muchas personas resistieron, guardaron sus tradiciones y lucharon por la libertad."], ex: { t: "¿Cuánto es un millón?", m: "un vaso pequeño, frijoles o granos de arroz, papel y lápiz", p: ["Llena el vasito de frijoles y cuenta cuántos entraron (pide ayuda para contar de diez en diez).", "Piensa: ¿cuántos vasitos harían falta para llegar a mil? ¿Y a un millón?", "Conversa con un adulto: cada frijol sería una persona con nombre, familia y sueños."] }, at: "¿Qué es la libertad?", m: "papel, lápices de colores", p: ["Piensa en lo que significa ser libre: elegir, jugar, estar con la familia, aprender.", "Dibuja lo que la libertad significa para ti.", "Pégalo en el álbum y escribe debajo: “La libertad es un derecho de todos”."], q: "¿Por qué es importante recordar las partes tristes de la historia?" } },

{ e: "✊", art: { b: "⛰️", s: ["✊", "🌽", "🛖", "⭐"], c: ["#1B3A0B", "#5A8A2C"] },
pt: { h: "Leo perguntou se as pessoas escravizadas tinham conseguido fugir. “Muitas conseguiram”, respondeu o vovô, “e construíram lugares livres nas matas e nas serras, chamados quilombos.” Nina arregalou os olhos quando ele contou que um deles durou quase cem anos.", t: "Quilombos: lugares de liberdade", f: "Quilombos eram comunidades formadas por pessoas que fugiram da escravidão. Lá elas plantavam, criavam animais, faziam festas e se defendiam. O maior e mais famoso foi o Quilombo dos Palmares, em Alagoas.", x: "Palmares durou quase 100 anos e chegou a ter milhares de moradores! Seu líder mais conhecido foi Zumbi, e o dia 20 de novembro, Dia da Consciência Negra, homenageia sua luta.", s: ["Dandara, companheira de Zumbi, também é lembrada como uma guerreira de Palmares.", "Em Palmares se plantavam milho, feijão, mandioca e banana.", "Ainda hoje existem milhares de comunidades quilombolas no Brasil, que mantêm suas tradições."], ex: { t: "Feijão que brota", m: "um copo transparente, algodão, água, alguns grãos de feijão", p: ["Coloque algodão molhado no fundo do copo e ponha os feijões por cima.", "Deixe num lugar claro e molhe o algodão um pouquinho todo dia.", "Observe por uma semana: as raízes e as folhas vão aparecendo! Assim começavam as roças dos quilombos."] }, at: "Bandeira da coragem", m: "papel, lápis de cor, um palito", p: ["Desenhe Zumbi e Dandara, ou um símbolo de coragem que você inventar.", "Escreva uma palavra que combine com a luta deles: coragem, união, liberdade.", "Faça uma bandeirinha com o palito e cole uma cópia no álbum."], q: "O que é preciso para uma comunidade viver unida?" },
en: { h: "Leo asked whether enslaved people had managed to escape. “Many did,” Grandpa answered, “and they built free places in the forests and mountains, called quilombos.” Nina's eyes went wide when he told them one of them lasted almost a hundred years.", t: "Quilombos: places of freedom", f: "Quilombos were communities formed by people who escaped slavery. There they farmed, raised animals, held celebrations and defended themselves. The largest and most famous was the Quilombo dos Palmares, in the state of Alagoas.", x: "Palmares lasted almost 100 years and had thousands of residents! Its best-known leader was Zumbi, and November 20, Black Consciousness Day in Brazil, honors his struggle.", s: ["Dandara, Zumbi's partner, is also remembered as a warrior of Palmares.", "In Palmares people grew corn, beans, cassava and bananas.", "Today there are still thousands of quilombola communities in Brazil that keep their traditions alive."], ex: { t: "Sprouting beans", m: "a clear glass, cotton, water, a few dry beans", p: ["Put damp cotton in the bottom of the glass and place the beans on top.", "Leave it in a bright spot and moisten the cotton a little every day.", "Watch for a week: roots and leaves start to appear! That's how the quilombo fields began."] }, at: "Flag of courage", m: "paper, colored pencils, a stick", p: ["Draw Zumbi and Dandara, or a symbol of courage you invent.", "Write a word that fits their struggle: courage, unity, freedom.", "Make a little flag with the stick and glue a copy into the album."], q: "What does a community need to live together in unity?" },
es: { h: "Leo preguntó si las personas esclavizadas habían logrado escapar. “Muchas lo lograron”, respondió el abuelo, “y construyeron lugares libres en las selvas y las sierras, llamados quilombos.” Nina abrió grandes los ojos cuando él contó que uno de ellos duró casi cien años.", t: "Quilombos: lugares de libertad", f: "Los quilombos eran comunidades formadas por personas que huían de la esclavitud. Allí plantaban, criaban animales, hacían fiestas y se defendían. El más grande y famoso fue el Quilombo de los Palmares, en Alagoas.", x: "¡Palmares duró casi 100 años y llegó a tener miles de habitantes! Su líder más conocido fue Zumbi, y el 20 de noviembre, Día de la Conciencia Negra en Brasil, homenajea su lucha.", s: ["Dandara, compañera de Zumbi, también es recordada como una guerrera de Palmares.", "En Palmares se plantaban maíz, frijoles, mandioca y bananas.", "Todavía hoy existen miles de comunidades quilombolas en Brasil que mantienen sus tradiciones."], ex: { t: "Frijol que brota", m: "un vaso transparente, algodón, agua, algunos frijoles", p: ["Pon algodón mojado en el fondo del vaso y coloca los frijoles encima.", "Déjalo en un lugar con luz y moja un poquito el algodón cada día.", "Observa durante una semana: ¡van apareciendo las raíces y las hojas! Así empezaban los cultivos de los quilombos."] }, at: "Bandera del valor", m: "papel, lápices de colores, un palito", p: ["Dibuja a Zumbi y Dandara, o un símbolo de valentía que inventes.", "Escribe una palabra que combine con su lucha: valor, unión, libertad.", "Haz una banderita con el palito y pega una copia en el álbum."], q: "¿Qué hace falta para que una comunidad viva unida?" } },

{ e: "🥁", art: { b: "🥁", s: ["🎶", "💃", "🍲", "🪘"], c: ["#5A2A0B", "#E07A2C"] },
pt: { h: "Na praça, uma roda de capoeira tocava berimbau e atabaque. Leo começou a balançar no ritmo, e Nina bateu palmas junto com o coro. O vovô sorriu: “Muito do que faz o Brasil ser o Brasil veio da África: músicas, danças, comidas e até palavras que vocês falam todo dia.”", t: "A África dentro do Brasil", f: "Os africanos e seus descendentes trouxeram muitos saberes para o Brasil. A capoeira, o samba, o maracatu e o jongo têm raízes africanas, assim como comidas como o acarajé e muitas palavras do português.", x: "Palavras como caçula, cafuné, moleque e quitanda vieram de línguas africanas!", s: ["A roda de capoeira é Patrimônio Cultural Imaterial da Humanidade, reconhecida pela UNESCO em 2014.", "O berimbau é um instrumento de uma corda só, com uma cabaça que faz o som ficar mais forte.", "O ofício das baianas de acarajé é patrimônio cultural do Brasil."], ex: { t: "Mini berimbau", m: "uma caixinha ou pote de plástico aberto, elásticos de tamanhos diferentes, um lápis", p: ["Estique os elásticos ao redor da caixinha aberta.", "Belisque cada elástico e escute: os mais esticados fazem som mais agudo.", "Coloque um lápis por baixo dos elásticos como um cavalete: o som muda de novo! A caixa funciona como a cabaça do berimbau."] }, at: "Roda de palavras", m: "papel, lápis de cor", p: ["Escreva caçula, cafuné, moleque e quitanda num círculo.", "Desenhe uma cena para cada palavra.", "Pergunte à família se conhecem outras palavras de origem africana e cole no álbum."], q: "Qual música, dança ou comida de origem africana você mais gosta?" },
en: { h: "In the square, a capoeira circle was playing the berimbau and drums. Leo started swaying to the rhythm, and Nina clapped along with the chorus. Grandpa smiled: “So much of what makes Brazil Brazil came from Africa: music, dances, foods and even words you speak every day.”", t: "Africa inside Brazil", f: "Africans and their descendants brought lots of knowledge to Brazil. Capoeira, samba, maracatu and jongo all have African roots, as do foods like acarajé and many Portuguese words.", x: "Portuguese words like caçula (youngest child), cafuné (stroking someone's hair), moleque (kid) and quitanda (little grocery stall) came from African languages!", s: ["The capoeira circle is part of humanity's Intangible Cultural Heritage, recognized by UNESCO in 2014.", "The berimbau is a one-string instrument with a gourd that makes the sound louder.", "The craft of the baianas who make acarajé is part of Brazil's cultural heritage."], ex: { t: "Mini berimbau", m: "a small open box or plastic tub, rubber bands of different sizes, a pencil", p: ["Stretch the rubber bands around the open box.", "Pluck each band and listen: the tighter ones make a higher sound.", "Slide a pencil under the bands like a bridge: the sound changes again! The box works like the berimbau's gourd."] }, at: "Word circle", m: "paper, colored pencils", p: ["Write caçula, cafuné, moleque and quitanda in a circle.", "Draw a scene for each word.", "Ask your family if they know other words of African origin and glue it into the album."], q: "What African-rooted music, dance or food do you like best?" },
es: { h: "En la plaza, una rueda de capoeira tocaba berimbau y atabaque. Leo empezó a moverse al ritmo, y Nina aplaudió junto con el coro. El abuelo sonrió: “Mucho de lo que hace que Brasil sea Brasil vino de África: músicas, danzas, comidas y hasta palabras que ustedes dicen todos los días.”", t: "África dentro de Brasil", f: "Los africanos y sus descendientes trajeron muchos saberes a Brasil. La capoeira, la samba, el maracatu y el jongo tienen raíces africanas, igual que comidas como el acarajé y muchas palabras del portugués.", x: "¡Palabras del portugués como caçula (hijo menor), cafuné (caricia en el pelo), moleque (chiquillo) y quitanda (puestito de frutas) vinieron de lenguas africanas!", s: ["La rueda de capoeira es Patrimonio Cultural Inmaterial de la Humanidad, reconocida por la UNESCO en 2014.", "El berimbau es un instrumento de una sola cuerda, con una calabaza que hace el sonido más fuerte.", "El oficio de las bahianas del acarajé es patrimonio cultural de Brasil."], ex: { t: "Mini berimbau", m: "una cajita o pote de plástico abierto, gomitas elásticas de distintos tamaños, un lápiz", p: ["Estira las gomitas alrededor de la cajita abierta.", "Pellizca cada gomita y escucha: las más estiradas suenan más agudo.", "Pon un lápiz debajo de las gomitas como un puente: ¡el sonido cambia otra vez! La caja funciona como la calabaza del berimbau."] }, at: "Rueda de palabras", m: "papel, lápices de colores", p: ["Escribe caçula, cafuné, moleque y quitanda en un círculo.", "Dibuja una escena para cada palabra.", "Pregunta a tu familia si conocen otras palabras de origen africano y pégalo en el álbum."], q: "¿Qué música, danza o comida de origen africano te gusta más?" } },

{ e: "🍿", art: { b: "🍿", s: ["🌽", "🍍", "🐊", "🛏️"], c: ["#4E3A0B", "#E0B03A"] },
pt: { h: "O vovô estourou pipoca para a sessão de cinema em casa. Quando o Pipoca, o gato, veio correndo com o barulho, todos riram. “Sabiam que a palavra pipoca vem do tupi?”, perguntou o vovô. Leo ficou impressionado: “Então o nome do nosso gato é indígena!”", t: "Palavras e saberes indígenas", f: "Os povos indígenas ensinaram muita coisa a quem chegou depois: a plantar e preparar a mandioca, a dormir em redes, a usar plantas como remédio e a conhecer a floresta. E muitas palavras do português vieram de línguas como o tupi.", x: "Pipoca vem do tupi e quer dizer algo como “pele que estoura”. Abacaxi, mandioca, capivara, jacaré e jabuti também são palavras de origem tupi!", s: ["Muitos lugares do Brasil têm nomes indígenas, como Paraná, Ipanema, Guanabara e Curitiba.", "A tapioca e a farinha de mandioca são receitas criadas pelos povos indígenas.", "A rede de dormir é uma invenção indígena que se espalhou pelo mundo."], ex: { t: "Por que a pipoca estoura?", m: "milho de pipoca, uma panela com tampa, um pouco de óleo, um adulto no fogão", p: ["Com um adulto cuidando do fogão, coloque o óleo e o milho na panela tampada.", "Escute: dentro de cada grão há um pouquinho de água que vira vapor com o calor.", "O vapor empurra até a casca estourar e o milho virar do avesso! Espere esfriar antes de comer."] }, at: "Dicionário tupi", m: "caderninho, lápis de cor", p: ["Escreva as palavras pipoca, abacaxi, capivara, jacaré e mandioca, uma por página.", "Desenhe cada uma.", "Procure com um adulto o nome indígena de algum lugar perto de você e acrescente ao dicionário."], q: "Que nome de origem indígena você daria a um bichinho de estimação?" },
en: { h: "Grandpa made popcorn for movie night at home. When Popcorn the cat came running at the noise, everyone laughed. “Did you know the Portuguese word for popcorn, pipoca, comes from Tupi?” Grandpa asked. Leo was impressed: “So our cat's name is Indigenous!”", t: "Indigenous words and knowledge", f: "Indigenous peoples taught a lot to those who came later: how to grow and prepare cassava, sleep in hammocks, use plants as medicine and understand the forest. And many Portuguese words came from languages like Tupi.", x: "Pipoca comes from Tupi and means something like “skin that bursts.” The Portuguese words for pineapple (abacaxi), cassava (mandioca), capybara, alligator (jacaré) and tortoise (jabuti) come from Tupi too!", s: ["Many places in Brazil have Indigenous names, like Paraná, Ipanema, Guanabara and Curitiba.", "Tapioca and cassava flour are recipes created by Indigenous peoples.", "The hammock is an Indigenous invention that spread around the world."], ex: { t: "Why does popcorn pop?", m: "popcorn kernels, a pot with a lid, a little oil, a grown-up at the stove", p: ["With a grown-up handling the stove, put the oil and kernels in the covered pot.", "Listen: inside every kernel there's a tiny bit of water that turns into steam when heated.", "The steam pushes until the shell bursts and the kernel turns inside out! Wait for it to cool before eating."] }, at: "Tupi dictionary", m: "a small notebook, colored pencils", p: ["Write the words pipoca, abacaxi, capivara, jacaré and mandioca, one per page.", "Draw each one.", "With a grown-up, look up an Indigenous place name near you and add it to the dictionary."], q: "What Indigenous-origin name would you give a pet?" },
es: { h: "El abuelo hizo palomitas para la noche de cine en casa. Cuando Palomita, el gato, vino corriendo por el ruido, todos se rieron. “¿Sabían que la palabra portuguesa para palomitas, pipoca, viene del tupí?”, preguntó el abuelo. Leo quedó impresionado: “¡Entonces el nombre de nuestro gato en portugués es indígena!”", t: "Palabras y saberes indígenas", f: "Los pueblos indígenas enseñaron mucho a quienes llegaron después: a cultivar y preparar la mandioca, a dormir en hamacas, a usar plantas como remedio y a conocer la selva. Y muchas palabras del portugués vinieron de lenguas como el tupí.", x: "Pipoca viene del tupí y quiere decir algo como “piel que revienta”. ¡Las palabras portuguesas para ananá (abacaxi), mandioca, carpincho (capivara), yacaré y tortuga (jabuti) también vienen del tupí!", s: ["Muchos lugares de Brasil tienen nombres indígenas, como Paraná, Ipanema, Guanabara y Curitiba.", "La tapioca y la harina de mandioca son recetas creadas por los pueblos indígenas.", "La hamaca es un invento indígena que se extendió por todo el mundo."], ex: { t: "¿Por qué revientan las palomitas?", m: "maíz pisingallo, una olla con tapa, un poco de aceite, un adulto en la cocina", p: ["Con un adulto a cargo de la cocina, pon el aceite y el maíz en la olla tapada.", "Escucha: dentro de cada grano hay un poquito de agua que se convierte en vapor con el calor.", "¡El vapor empuja hasta que la cáscara revienta y el grano se da vuelta! Espera que se enfríen antes de comer."] }, at: "Diccionario tupí", m: "cuadernito, lápices de colores", p: ["Escribe las palabras pipoca, abacaxi, capivara, jacaré y mandioca, una por página.", "Dibuja cada una.", "Busca con un adulto el nombre indígena de algún lugar cerca de ti y agrégalo al diccionario."], q: "¿Qué nombre de origen indígena le pondrías a una mascota?" } },
];
